for (const lg of LEAGUES) {
  const w = LEAGUES_W[lg.id];
  lg.nameHeW = w ? w[0] : lg.nameHe + ' לנשים';
  lg.shortHeW = w ? w[1] : lg.shortHe;
  lg.youthNameHeW = w ? w[2] : (lg.youthNameHe || 'ליגת הנוער') + ' לנערות';
  if (lg.cup) lg.cup.nameHeW = (w && w[3]) || lg.cup.nameHe + ' לנשים';
}

export const LEAGUE_BY_ID = {};
export const CLUB_INDEX = {};
for (const lg of LEAGUES) {
  LEAGUE_BY_ID[lg.id] = lg;
  for (const club of lg.clubs) CLUB_INDEX[club.id] = { club, leagueId: lg.id };
}
for (const club of EURO_FILLER_CLUBS) CLUB_INDEX[club.id] = { club, leagueId: null };
